static BlackGuestFunction black_resolve_guest_runtime_target(uint32_t guest_va)
{
    if (guest_va == 0x000A39F1u) return (BlackGuestFunction)black_trace_sub_A39F1;
    if (guest_va == 0x000301B0u) return (BlackGuestFunction)black_guest_pointer_sub_301B0;
    if (guest_va == 0x00030350u) return (BlackGuestFunction)black_guest_pointer_sub_30350;
    if (guest_va == 0x000303B0u) return (BlackGuestFunction)black_guest_pointer_sub_303B0;
    if (guest_va == 0x000A5886u) return (BlackGuestFunction)black_trace_sub_A5886;
    if (guest_va == 0x000A58AAu) return (BlackGuestFunction)black_trace_sub_A58AA;
    return black_resolve_guest_function(guest_va);
}

static BlackGuestFunction black_resolve_host_runtime_target(uint32_t host_va)
{
    size_t i;
    for (i = 0; i < sizeof(black_guest_functions) / sizeof(black_guest_functions[0]); ++i) {
        if ((uint32_t)(uintptr_t)black_guest_functions[i].host_function == host_va)
            return black_guest_functions[i].host_function;
    }
    return 0;
}

static void __cdecl black_rebase_registered_callbacks(void)
{
    static const uint32_t slots[] = { 0x0056A768u, 0x0056A76Cu, 0x0056A770u, 0x0056A774u };
    size_t i;
    uint32_t rebased = 0;
    for (i = 0; i < sizeof(slots) / sizeof(slots[0]); ++i) {
        uint32_t *slot;
        uint32_t guest_target;
        BlackGuestFunction host_target;
        if (!guest_image || slots[i] < BLACK_GUEST_IMAGE_BASE ||
            slots[i] - BLACK_GUEST_IMAGE_BASE > BLACK_GUEST_IMAGE_SIZE - sizeof(uint32_t)) return;
        slot = (uint32_t *)(guest_image + slots[i] - BLACK_GUEST_IMAGE_BASE);
        guest_target = *slot;
        host_target = black_resolve_guest_runtime_target(guest_target);
        if (!host_target) {
            trace_log("event=guest_callback_unresolved slot=0x%08X value=0x%08X\n", slots[i], guest_target);
            continue;
        }
        *slot = (uint32_t)(uintptr_t)host_target;
        if (*slot != (uint32_t)(uintptr_t)host_target) return;
        trace_log("event=guest_callback_rebased slot=0x%08X guest=0x%08X host=0x%08X\n",
            slots[i], guest_target, *slot);
        ++rebased;
    }
    trace_log("event=guest_callback_table_rebased slots=4 rebased=%u\n", rebased);
}

