    memcpy(black_a3a31_trampoline + 6, &jump_displacement, sizeof(jump_displacement));
    FlushInstructionCache(GetCurrentProcess(), black_a3a31_trampoline, 10);
    if (!VirtualProtect(target, sizeof(branch), PAGE_EXECUTE_READWRITE, &old_protection)) return 0;
    jump_displacement = (int32_t)((uint32_t)(uintptr_t)black_trace_sub_A3A31 - (uint32_t)(uintptr_t)(target + 5));
    memcpy(branch + 1, &jump_displacement, sizeof(jump_displacement));
